@push('scripts')<script>
(()=>{
const search=document.getElementById('purchase-search'),results=document.getElementById('purchase-results'),lines=document.getElementById('purchase-lines'),entry=document.getElementById('new-product-entry');
const newName=document.getElementById('new-product-name');let products=[],timer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
function renumber(){[...lines.querySelectorAll('[data-line]')].forEach((row,i)=>row.querySelectorAll('[data-field]').forEach(input=>input.name=`items[${i}][${input.dataset.field}]`))}
function render(){
 if(!products.length){lines.innerHTML='<div class="empty-state compact"><div class="empty-icon">＋</div><b>No items added</b><p>Search for a variant to receive.</p></div>';recalc();return}
 lines.innerHTML=`<table><thead><tr><th>PRODUCT / VARIANT</th><th>QTY</th><th>UNIT COST ₹</th><th>DISCOUNT ₹</th><th>TAX %</th><th></th></tr></thead><tbody>${products.map((p,i)=>`<tr data-line><td class="table-primary">${esc(p.name)}<small class="purchase-sku">${esc(p.sku||'SKU generated on save')}${p.size||p.colour?' · '+esc([p.size,p.colour].filter(Boolean).join(' · ')):''}</small>${p.newProduct?`<input data-field="new_product_name" type="hidden" value="${esc(p.name)}"><input data-field="new_product_category" type="hidden" value="${esc(p.category)}"><input data-field="new_product_brand" type="hidden" value="${esc(p.brand)}"><input data-field="size" type="hidden" value="${esc(p.size)}"><input data-field="colour" type="hidden" value="${esc(p.colour)}"><input data-field="sku" type="hidden" value="${esc(p.sku)}"><input data-field="barcode" type="hidden" value="${esc(p.barcode)}"><input data-field="selling_price" type="hidden" value="${p.price}">`:`<input data-field="variant_id" type="hidden" value="${p.id}">`}</td><td><input data-field="quantity" type="number" min="1" step="1" value="1" required></td><td><input data-field="unit_cost" type="number" min="0" step="0.01" value="${Number(p.cost||0).toFixed(2)}" required></td><td><input data-field="discount" type="number" min="0" step="0.01" value="0"></td><td><input data-field="tax_rate" type="number" min="0" max="100" step="0.01" value="${Number(p.tax||0)}"></td><td><button type="button" class="remove-split" data-remove="${i}" aria-label="Remove item">×</button></td></tr>`).join('')}</tbody></table>`;
 renumber();recalc()
}
function recalc(){let sub=0,disc=0,tax=0;products.forEach((p,i)=>{const row=lines.querySelectorAll('[data-line]')[i];if(!row)return;const qty=Number(row.querySelector('[data-field="quantity"]').value)||0,cost=Number(row.querySelector('[data-field="unit_cost"]').value)||0,d=Math.min(Number(row.querySelector('[data-field="discount"]').value)||0,qty*cost),rate=Number(row.querySelector('[data-field="tax_rate"]').value)||0;sub+=qty*cost;disc+=d;tax+=Math.round((qty*cost-d)*rate)/100});const billDisc=Math.min(Number(document.getElementById('purchase-discount').value)||0,Math.max(0,sub-disc)),total=Math.round((Math.max(0,sub-disc-billDisc)+tax)*100)/100,paid=Number(document.getElementById('purchase-paid').value)||0;document.getElementById('purchase-total').textContent=money(total);document.getElementById('purchase-balance').textContent=money(Math.max(0,total-paid))}
search.addEventListener('input',()=>{clearTimeout(timer);const q=search.value.trim();entry.classList.add('hidden');if(!q){results.classList.add('hidden');return}timer=setTimeout(async()=>{try{const r=await fetch(`{{ route('products.search') }}?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'}});const data=await r.json();results.dataset.items=JSON.stringify(data);results.innerHTML=data.length?data.map(v=>`<button type="button" class="search-result" data-add="${v.id}"><span><b>${esc(v.name)}</b><small>${esc(v.sku)}${v.size||v.colour?' · '+esc([v.size,v.colour].filter(Boolean).join(' · ')):''}</small></span><span><small>Current stock ${v.stock}</small></span></button>`).join(''):`<div class="search-empty">No catalogue match. <button type="button" class="text-link" data-create>＋ Add “${esc(q)}” as a new product</button></div>`;results.classList.remove('hidden')}catch(e){results.innerHTML='<div class="search-empty">Search failed. Try again.</div>';results.classList.remove('hidden')}},180)});
results.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const p=JSON.parse(results.dataset.items||'[]').find(x=>x.id==add.dataset.add);if(!p)return;const old=products.find(x=>!x.newProduct&&x.id===p.id);if(old){const row=lines.querySelectorAll('[data-line]')[products.indexOf(old)];row.querySelector('[data-field="quantity"]').value=Number(row.querySelector('[data-field="quantity"]').value)+1}else products.push(p);search.value='';results.classList.add('hidden');render();search.focus();return}if(e.target.closest('[data-create]')){newName.value=search.value.trim();entry.classList.remove('hidden');results.classList.add('hidden');newName.focus()}});
document.getElementById('queue-new-product').addEventListener('click',()=>{const priceInput=document.getElementById('new-product-price');if(!newName.value.trim()){newName.setCustomValidity('Enter the product name.');newName.reportValidity();newName.setCustomValidity('');return}if(!priceInput.value||Number(priceInput.value)<=0){priceInput.setCustomValidity('Enter a selling price greater than zero.');priceInput.reportValidity();priceInput.setCustomValidity('');return}products.push({id:`new-${Date.now()}-${Math.random()}`,newProduct:true,name:newName.value.trim(),category:document.getElementById('new-product-category').value.trim(),brand:document.getElementById('new-product-brand').value.trim(),size:document.getElementById('new-product-size').value.trim(),colour:document.getElementById('new-product-colour').value.trim(),sku:document.getElementById('new-product-sku').value.trim(),barcode:document.getElementById('new-product-barcode').value.trim(),price:Number(priceInput.value),tax:Number(document.getElementById('new-product-tax').value)||0,cost:0});entry.classList.add('hidden');entry.querySelectorAll('input').forEach(input=>{if(input.id==='new-product-tax')input.value='0';else input.value=''});render()});
document.getElementById('cancel-new-product').addEventListener('click',()=>entry.classList.add('hidden'));
lines.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){products.splice(Number(b.dataset.remove),1);render()}});lines.addEventListener('input',recalc);document.getElementById('purchase-discount').addEventListener('input',recalc);document.getElementById('purchase-paid').addEventListener('input',recalc);document.addEventListener('keydown',e=>{if(e.key==='Escape'){results.classList.add('hidden');entry.classList.add('hidden')}});
document.getElementById('purchase-form').addEventListener('submit',e=>{if(!products.length){e.preventDefault();window.showToast('Add at least one item to this GRN.');return}renumber()});
})();
</script>@endpush
